import { HABILIDADES, NIVEIS } from '../data/habilidades.js'

const EXEMPLO = [
  { habilidade: 'reconhecer-emocoes', nivel: 1 },
  { habilidade: 'resposta-social', nivel: 2 },
  { habilidade: 'causa-efeito-social', nivel: 1 },
]

export default function Pdi({ pdi, setPdi, avancar }) {
  const itemDe = (id) => pdi.itens.find((i) => i.habilidade === id)

  function alternar(id) {
    const itens = itemDe(id)
      ? pdi.itens.filter((i) => i.habilidade !== id)
      : [...pdi.itens, { habilidade: id, nivel: 1 }]
    setPdi({ ...pdi, itens })
  }

  function mudarNivel(id, nivel) {
    setPdi({
      ...pdi,
      itens: pdi.itens.map((i) => (i.habilidade === id ? { ...i, nivel: Number(nivel) } : i)),
    })
  }

  return (
    <section className="tela">
      <h2>PDI da criança</h2>
      <p>Marque as habilidades a desenvolver e o nível atual da criança em cada uma.</p>
      <label className="campo">
        Nome da criança (opcional)
        <input value={pdi.nome} onChange={(e) => setPdi({ ...pdi, nome: e.target.value })} />
      </label>

      <ul className="lista">
        {HABILIDADES.map((h) => {
          const item = itemDe(h.id)
          return (
            <li key={h.id} className="linha">
              <label>
                <input type="checkbox" checked={!!item} onChange={() => alternar(h.id)} /> {h.nome}
              </label>
              {item && (
                <select value={item.nivel} onChange={(e) => mudarNivel(h.id, e.target.value)}>
                  {NIVEIS.map((n) => (
                    <option key={n.valor} value={n.valor}>
                      Nível {n.valor} – {n.nome}
                    </option>
                  ))}
                </select>
              )}
            </li>
          )
        })}
      </ul>

      <div className="acoes">
        <button className="secundario" onClick={() => setPdi({ ...pdi, itens: EXEMPLO })}>
          Preencher exemplo
        </button>
        <button disabled={pdi.itens.length === 0} onClick={avancar}>
          Continuar
        </button>
      </div>
    </section>
  )
}

import { HIPERFOCOS } from '../data/hiperfocos.js'

export default function EscolhaHiperfoco({ nome, escolher }) {
  return (
    <section className="tela">
      <h2>{nome ? `${nome}, do que` : 'Do que'} você mais gosta?</h2>
      <div className="grade">
        {HIPERFOCOS.map((h) => (
          <button
            key={h.id}
            className="cartao-grande"
            style={{ background: h.cor }}
            onClick={() => escolher(h)}
          >
            <span className="emoji-grande">{h.emoji}</span>
            {h.nome}
          </button>
        ))}
      </div>
    </section>
  )
}

import { useMemo } from 'react'
import { JOGOS } from '../data/jogos.js'
import { recomendar } from '../recomendacao.js'
import { estado } from '../progresso.js'

const VELOCIDADES = [
  { valor: 0.7, nome: 'Lenta' },
  { valor: 1, nome: 'Normal' },
  { valor: 1.4, nome: 'Rápida' },
]

export default function Jogos({ pdi, hiperfoco, opcoes, setOpcoes, jogar, verColecao, trocar }) {
  const recomendados = useMemo(() => recomendar(pdi.itens, JOGOS), [pdi])
  const e = estado(hiperfoco)

  return (
    <section className="tela">
      <h2>
        {hiperfoco.emoji} Jogos para {pdi.nome || 'a criança'}
      </h2>
      <p>
        Hiperfoco: <strong>{hiperfoco.nome}</strong> · {e.total} acertos ·{' '}
        {e.desbloqueados.length}/{hiperfoco.itens.length} itens
      </p>

      <div className="opcoes">
        <label>
          Velocidade{' '}
          <select
            value={opcoes.velocidade}
            onChange={(ev) => setOpcoes({ ...opcoes, velocidade: Number(ev.target.value) })}
          >
            {VELOCIDADES.map((v) => (
              <option key={v.valor} value={v.valor}>
                {v.nome}
              </option>
            ))}
          </select>
        </label>
        <label>
          <input
            type="checkbox"
            checked={!opcoes.efeitos}
            onChange={(ev) => setOpcoes({ ...opcoes, efeitos: !ev.target.checked })}
          />{' '}
          Reduzir efeitos
        </label>
      </div>

      <ul className="lista">
        {recomendados.map((r, i) => (
          <li key={r.jogo.id} className="cartao">
            <div>
              <h3>
                {r.jogo.emoji} {r.jogo.nome} {i === 0 && <span className="selo">Mais indicado</span>}
              </h3>
              <p>{r.jogo.descricao}</p>
              <small>
                Ritmo {r.jogo.ritmo} · Trabalha: {r.motivo}
              </small>
            </div>
            <button onClick={() => jogar(r)}>Jogar</button>
          </li>
        ))}
      </ul>

      <div className="acoes">
        <button className="secundario" onClick={verColecao}>
          Minha coleção
        </button>
        <button className="secundario" onClick={trocar}>
          Trocar hiperfoco
        </button>
      </div>
    </section>
  )
}

import { LIMITES, estado } from '../progresso.js'

export default function Colecao({ hiperfoco, voltar }) {
  const e = estado(hiperfoco)

  return (
    <section className="tela">
      <h2>
        {hiperfoco.emoji} Coleção de {hiperfoco.nome}
      </h2>
      <p>{e.total} acertos no total</p>
      <div className="grade">
        {hiperfoco.itens.map((item, i) => {
          const livre = e.total >= LIMITES[i]
          return (
            <div key={item.nome} className={livre ? 'item' : 'item bloqueado'}>
              <span className="emoji-grande">{livre ? item.emoji : '❓'}</span>
              {livre ? item.nome : `Faltam ${LIMITES[i] - e.total} acertos`}
            </div>
          )
        })}
      </div>
      <div className="acoes">
        <button onClick={voltar}>Voltar</button>
      </div>
    </section>
  )
}

import { useState } from 'react'
import PhaserGame from './PhaserGame'
import Pdi from './telas/Pdi'
import EscolhaHiperfoco from './telas/EscolhaHiperfoco'
import Jogos from './telas/Jogos'
import Colecao from './telas/Colecao'
import { estado, registrarAcerto } from './progresso.js'
import './App.css'

// Telas: pdi -> hiperfoco -> jogos -> (jogo | colecao)
function App() {
  const [tela, setTela] = useState('pdi')
  const [pdi, setPdi] = useState({ nome: '', itens: [] })
  const [hiperfoco, setHiperfoco] = useState(null)
  const [opcoes, setOpcoes] = useState({ velocidade: 1, efeitos: true })
  const [partida, setPartida] = useState(null)

  const ctx = partida && {
    hiperfoco,
    nivel: partida.nivel,
    velocidade: opcoes.velocidade,
    efeitos: opcoes.efeitos,
    sair: () => setTela('jogos'),
    estado: () => estado(hiperfoco),
    registrarAcerto: () => registrarAcerto(hiperfoco),
  }

  return (
    <main>
      <h1>Hackathon Dopamine</h1>
      {tela === 'pdi' && <Pdi pdi={pdi} setPdi={setPdi} avancar={() => setTela('hiperfoco')} />}
      {tela === 'hiperfoco' && (
        <EscolhaHiperfoco
          nome={pdi.nome}
          escolher={(h) => {
            setHiperfoco(h)
            setTela('jogos')
          }}
        />
      )}
      {tela === 'jogos' && (
        <Jogos
          pdi={pdi}
          hiperfoco={hiperfoco}
          opcoes={opcoes}
          setOpcoes={setOpcoes}
          jogar={(r) => {
            setPartida({ cena: r.jogo.cena, nivel: r.nivel })
            setTela('jogo')
          }}
          verColecao={() => setTela('colecao')}
          trocar={() => setTela('hiperfoco')}
        />
      )}
      {tela === 'colecao' && <Colecao hiperfoco={hiperfoco} voltar={() => setTela('jogos')} />}
      {tela === 'jogo' && <PhaserGame key={partida.cena} cena={partida.cena} ctx={ctx} />}
    </main>
  )
}

export default App

